/// The page itself.
///
/// A [`fmt::Display`] rather than a function that returns a string, because then the tests read the
/// same page the file gets and there is no second rendering path that could differ from it.
#[derive(Debug)]
pub struct Page<'a> {
    run: &'a Isolated,
    provenance: &'a Provenance,
    sweep: Option<&'a Sweep>,
    cost: Option<&'a Cost>,
    spent: Option<&'a Spent>,
}

impl<'a> Page<'a> {
    /// The page for one corpus run.
    #[must_use]
    pub const fn of(run: &'a Isolated, provenance: &'a Provenance) -> Self {
        Self { run, provenance, sweep: None, cost: None, spent: None }
    }

    /// The same page with the most recent function sweep carried onto it.
    ///
    /// Optional because a machine that has never run one still gets a page, and function coverage
    /// goes back to being named under the numbers nothing measures yet rather than being left off.
    #[must_use]
    pub const fn with(mut self, sweep: Option<&'a Sweep>) -> Self {
        self.sweep = sweep;
        self
    }

    /// The same page with the most recent cost run carried onto it.
    ///
    /// Carried and not computed, for the same reason the sweep is. Optional for the same reason too,
    /// and on a machine that has never run one the three resource ratios go back to being named under
    /// the numbers nothing measures yet.
    #[must_use]
    pub const fn with_cost(mut self, cost: Option<&'a Cost>) -> Self {
        self.cost = cost;
        self
    }

    /// The same page with the most recent corpus cost run carried onto it.
    ///
    /// Beside the benchmark one rather than instead of it. The two measure different things and the
    /// page says which is which, because a reader who saw one set of ratios and assumed it was the
    /// other would draw the wrong conclusion from a true number.
    #[must_use]
    pub const fn with_records(mut self, spent: Option<&'a Spent>) -> Self {
        self.spent = spent;
        self
    }
}

impl fmt::Display for Page<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let run = self.run;
        let p = self.provenance;
        writeln!(f, "# rudb against DuckDB")?;
        writeln!(f)?;
        writeln!(
            f,
            "Written by `rudb-compat report` at {}. This page is generated and never edited by hand, so anything wrong on it is wrong in the harness.",
            p.stamp
        )?;
        writeln!(f)?;
        writeln!(
            f,
            "Every number here has the denominator it was computed over printed beside it, there is no single headline percentage anywhere on it, and the numbers nothing measures yet are listed under a heading of their own rather than left out. The provenance of the whole run is at the bottom."
        )?;
        writeln!(f)?;

        writeln!(f, "## The corpus")?;
        writeln!(f)?;
        if p.upstream {
            writeln!(
                f,
                "DuckDB's own sqllogictest suite at {}, run against {} at {}.",
                p.corpus_ref, p.rudb, p.rudb_commit
            )?;
        } else {
            writeln!(
                f,
                "The files under {}, which is not the upstream corpus, run against {} at {}. The numbers below are about that directory and they are not the published number.",
                p.corpus_path, p.rudb, p.rudb_commit
            )?;
        }
        writeln!(f)?;
        writeln!(f, "    files       {:>7}", run.files)?;
        writeln!(f, "    attempted   {:>7}  records that ran", run.attempted())?;
        writeln!(f, "    passed      {:>7}", run.passed)?;
        writeln!(f, "    failed      {:>7}", run.failed)?;
        writeln!(f, "    pass rate   {:>6.1} percent of attempted", run.rate() * 100.0)?;
        writeln!(f)?;
        writeln!(
            f,
            "{} records were not attempted at all and none of them are in the rate above. That is the number to read beside the rate, because a runner that skips everything it would fail reports a hundred percent.",
            run.skips.total()
        )?;
        writeln!(f)?;
        for (gap, count) in run.skips.by_gap() {
            writeln!(f, "    {count:>7}  {:<10}{}", gap.name(), gap.blurb())?;
        }
        writeln!(f)?;
        let files = run.skipped_files.len();
        let cut = run.stopped.len();
        writeln!(
            f,
            "    {files:>7}  not run   files the runner never opened, whose records are on the rows above"
        )?;
        writeln!(
            f,
            "    {cut:>7}  cut off   files killed part way through, whose records are in neither column"
        )?;
        writeln!(f)?;

        if !run.kinds.is_empty() {
            writeln!(f, "## Statements")?;
            writeln!(f)?;
            writeln!(
                f,
                "The first of the three level two denominators, computed by this run, over the {} alternatives of the Statement rule in the vendored grammar. A kind counts when every record of it either did what the file said or failed the way the file said it fails. That is section 1.2 read strictly: one failing record takes the whole kind out however many passed beside it, and a kind counts as nothing at all until a record of it has run.",
                Kinds::surface().len()
            )?;
            writeln!(f)?;
            let supported = run.kinds.supported();
            let failing = run.kinds.failing();
            let untouched = run.kinds.untouched();
            let surface = Kinds::surface().len();
            writeln!(f, "    supported   {:>7}  of {surface} statement kinds", supported.len())?;
            writeln!(
                f,
                "    failing     {:>7}  at least one record of it did something else",
                failing.len()
            )?;
            writeln!(
                f,
                "    untouched   {:>7}  no record in this corpus is one, so nothing is measured",
                untouched.len()
            )?;
            writeln!(
                f,
                "    coverage    {:>7.1}  percent of the {surface}, which is the published number",
                run.kinds.rate() * 100.0
            )?;
            writeln!(f)?;
            if supported.is_empty() {
                writeln!(
                    f,
                    "Coverage is zero while every kind the corpus writes has at least one record that did something else, which is section 1.2 working as intended rather than an engine that answers nothing. Early on the per kind table below is the thing to read, because a kind with four thousand passes and one failure counts the same in the row above as a kind with no passes at all."
                )?;
                writeln!(f)?;
            }
            writeln!(
                f,
                "{} records that ran were sorted into a kind and {} more could not be, because the vendored grammar does not accept them. Most of those are the corpus writing a syntax error on purpose, since a file of `statement error` records is full of them, and the rest are a hole in the grammar or the tokenizer, which is ours. The sorting is done by the parser rather than by the first word, because `WITH x AS (...) INSERT INTO t SELECT * FROM x` starts with WITH and is an insert.",
                run.kinds.records(),
                run.kinds.unclassified
            )?;
            writeln!(f)?;
            writeln!(f, "### Per kind")?;
            writeln!(f)?;
            writeln!(f, "    {:<30}{:>9}{:>9}{:>9}", "kind", "records", "passed", "failed")?;
            for (kind, tally) in run.kinds.rows() {
                writeln!(
                    f,
                    "    {:<30}{:>9}{:>9}{:>9}",
                    fitted(kind, 29),
                    tally.records(),
                    tally.passed,
                    tally.failed
                )?;
            }
            writeln!(f)?;
            if untouched.is_empty() {
                writeln!(f, "Every kind the grammar has is in the table above.")?;
            } else if untouched.len() == 1 {
                writeln!(
                    f,
                    "The one kind with no record in this corpus, which is the figure to read beside the coverage number the way section 11.3 reads the zero weight names beside function coverage: {}.",
                    untouched[0]
                )?;
            } else {
                writeln!(
                    f,
                    "The {} kinds with no record in this corpus, which is the figure to read beside the coverage number the way section 11.3 reads the zero weight names beside function coverage: {}.",
                    untouched.len(),
                    untouched.join(", ")
                )?;
            }
            writeln!(f)?;
        }

        writeln!(f, "## Failures by reason")?;
        writeln!(f)?;
        writeln!(
            f,
            "All nine reasons, including the ones at zero, because this page is read as a series and a row that comes and goes is a row nobody can follow. The shape of this list says more than the pass rate does: fifty thousand not implemented and fifty wrong answers is a young engine, and the other way round at the same rate is a crisis."
        )?;
        writeln!(f)?;
        let reasons = run.reasons();
        for reason in Reason::ALL {
            writeln!(
                f,
                "    {:>7}  {:<16}{}",
                reasons.count(reason),
                reason.name(),
                reason.blurb()
            )?;
        }
        writeln!(f)?;
        let wrong = reasons.count(Reason::WrongAnswer);
        if wrong == 0 {
            writeln!(f, "No wrong answers, which is the row that matters.")?;
        } else {
            writeln!(f, "{wrong} wrong answers, every one of them a bug at priority p0.")?;
        }
        writeln!(f)?;

        if let Some(sweep) = self.sweep {
            writeln!(f, "## Function coverage")?;
            writeln!(f)?;
            writeln!(
                f,
                "Not measured by this run. The sweep behind this number puts every generated call to every overload in duckdb_functions() to both engines and takes about forty minutes, and this page comes out of a corpus run, so the number below is the most recent sweep written down beside these pages and it is carried here rather than computed here."
            )?;
            writeln!(f)?;
            let line = |f: &mut fmt::Formatter<'_>, what: &str, tally: &Tally| {
                writeln!(
                    f,
                    "    {what:<12}{:>6} of {:<6}{:>5.1} percent, with {} failed and {} never tested",
                    tally.passed,
                    tally.total,
                    tally.share() * 100.0,
                    tally.failed,
                    tally.untested
                )
            };
            line(f, "names", &sweep.names)?;
            line(f, "overloads", &sweep.overloads)?;
            writeln!(f)?;
            writeln!(
                f,
                "An overload that was never tested is a gap in this harness rather than a gap in the engine, and there are three of those. They are counted against the denominator all the same, because a name nothing tested is a name nobody can claim."
            )?;
            writeln!(f)?;
            for (why, count) in &sweep.reasons {
                writeln!(f, "    {count:>7}  {}", why.name())?;
            }
            writeln!(f)?;
            if sweep.crashes > 0 {
                writeln!(
                    f,
                    "{} calls made one of the two engines panic rather than answer, and every one of those is a bug in the engine that panicked rather than a difference between the two.",
                    sweep.crashes
                )?;
                writeln!(f)?;
            }
            writeln!(
                f,
                "This is the unweighted number. The weighted one section 1.1 also asks for needs the real query corpus to weight by, and that corpus does not exist yet."
            )?;
            writeln!(f)?;
            writeln!(f, "    measured    {} on {}", sweep.stamp, sweep.host)?;
            writeln!(f, "    engine      {} at {}", sweep.rudb, sweep.rudb_commit)?;
            writeln!(f, "    rudb-compat {}", sweep.compat_commit)?;
            writeln!(f, "    duckdb      {}", sweep.duckdb_version)?;
            writeln!(f)?;
            if sweep.matches(p) {
                writeln!(
                    f,
                    "That is the same engine build on the same machine as the corpus numbers above, so this page is one measurement."
                )?;
            } else {
                writeln!(
                    f,
                    "That is not the engine build and machine the corpus numbers above came from, so the two halves of this page are two measurements and not one."
                )?;
            }
            writeln!(f)?;
        }

        if let Some(cost) = self.cost {
            writeln!(f, "## Resources")?;
            writeln!(f)?;
            writeln!(
                f,
                "Not measured by this run either. These come off the benchmark corpus, where every file carries its own load and one query, and they are carried here from the most recent `rudb-compat cost` run written down beside these pages. The sqllogictest corpus above is measured separately and the section under this one has it, because a benchmark suite measures the shapes somebody chose and a corpus measures the shapes nobody chose, and an engine can be quick on the first and quadratic on the second."
            )?;
            writeln!(f)?;
            writeln!(
                f,
                "Each number is rudb over the pinned binary, so one is even and the goal in section 11.6 is 0.1 on all three. The median of several runs with the quartiles beside it, never the minimum. Three numbers and not one, because they fail differently: an engine can be fast and enormous, which is a chunk size, and it can be even on wall clock and far behind on processor time, which is an engine getting its speed from cores rather than from work."
            )?;
            writeln!(f)?;
            writeln!(f, "    benchmarks  {:>7}  measured on both engines", cost.measured)?;
            writeln!(
                f,
                "    refused     {:>7}  one engine declined it or took too long",
                cost.refused
            )?;
            writeln!(f, "    skipped     {:>7}  never put to an engine", cost.skipped)?;
            writeln!(f)?;
            match cost.overall {
                None => {
                    writeln!(
                        f,
                        "No benchmark was measured on both engines in that run, so there is no ratio over the whole corpus. The counts above say why."
                    )?;
                    writeln!(f)?;
                }
                Some(ratios) => {
                    writeln!(f, "### The whole corpus")?;
                    writeln!(f)?;
                    for (what, spread) in
                        [("time", ratios.time), ("cpu", ratios.cpu), ("memory", ratios.memory)]
                    {
                        writeln!(
                            f,
                            "    {what:<8}{:>8.2}   quartiles {:.2} to {:.2} over {} benchmarks",
                            spread.median, spread.low, spread.high, spread.count
                        )?;
                    }
                    writeln!(f)?;
                    if ratios.at_goal() {
                        writeln!(f, "All three medians are at or below the goal of a tenth.")?;
                    } else {
                        writeln!(
                            f,
                            "The goal is {:.1} on all three and this is not at it yet. A feature that lands correct and slow is still better than a feature that does not land, per section 11.6, and the number is here so that nobody has to take anybody's word for where it is.",
                            Ratios::GOAL
                        )?;
                    }
                    writeln!(f)?;
                    writeln!(
                        f,
                        "A benchmark here is the load and the query in one process, because rudb has no storage format yet, tamnd/rudb#103, so there is no way to build a table once and then time a query against it. Some of the median number above is therefore the load rather than the query, {:.0} percent of it, taken on the side that answers everything. The row counts are cut down to a million, so these are ratios at a million rows and they say nothing about a ratio at a hundred million.",
                        cost.load_share * 100.0
                    )?;
                    writeln!(f)?;
                }
            }
            if !cost.groups.is_empty() {
                writeln!(f, "### Per suite")?;
                writeln!(f)?;
                writeln!(
                    f,
                    "Worst median wall clock first. A suite with one benchmark in it is left out, because one benchmark is an anecdote and putting it in a table beside a suite of a hundred invites somebody to read it as a trend."
                )?;
                writeln!(f)?;
                writeln!(
                    f,
                    "    {:<24}{:>9}{:>9}{:>9}{:>7}",
                    "suite", "time", "cpu", "memory", "n"
                )?;
                for (group, ratios) in &cost.groups {
                    writeln!(
                        f,
                        "    {group:<24}{:>9.2}{:>9.2}{:>9.2}{:>7}",
                        ratios.time.median,
                        ratios.cpu.median,
                        ratios.memory.median,
                        ratios.time.count
                    )?;
                }
                writeln!(f)?;
            }
            if !cost.worst.is_empty() {
                writeln!(f, "### The worst {}", cost.worst.len())?;
                writeln!(f)?;
                writeln!(
                    f,
                    "This is the column that gets read. An engine that is even on average and two hundred times slower on one shape has a bug rather than a distribution, and an average hides that by construction. The load share says how much of each row is building the tables rather than reading them, so a row at ninety percent is an ingestion problem and a row at ten is a query problem."
                )?;
                writeln!(f)?;
                writeln!(
                    f,
                    "    {:<40}{:>9}{:>9}{:>9}{:>8}",
                    "benchmark", "time", "cpu", "memory", "load"
                )?;
                for one in &cost.worst {
                    writeln!(
                        f,
                        "    {:<40}{:>9.2}{:>9.2}{:>9.2}{:>7.0}%",
                        fitted(&one.name, 39),
                        one.time,
                        one.cpu,
                        one.memory,
                        one.load_share * 100.0
                    )?;
                }
                writeln!(f)?;
            }
            writeln!(f, "    measured    {} on {}", cost.stamp, cost.host)?;
            writeln!(f, "    engine      {} at {}", cost.rudb, cost.rudb_commit)?;
            writeln!(f, "    rudb-compat {}", cost.compat_commit)?;
            writeln!(f, "    duckdb      {}", cost.duckdb_version)?;
            writeln!(f)?;
            if cost.matches(p) {
                writeln!(
                    f,
                    "That is the same engine build on the same machine as the corpus numbers above."
                )?;
            } else {
                writeln!(
                    f,
                    "That is not the engine build and machine the corpus numbers above came from. Section 11.2 says the resource numbers need their provenance more than the correctness numbers do, and this is the case it was written for: a ratio whose two sides came off different hardware is not a ratio."
                )?;
            }
            writeln!(f)?;
        }

        if let Some(spent) = self.spent {
            writeln!(f, "## Resources per corpus record")?;
            writeln!(f)?;
            writeln!(
                f,
                "The same three ratios over the sqllogictest corpus above rather than over the benchmark corpus, carried here from the most recent `rudb-compat records` run written down beside these pages. A benchmark suite measures the shapes somebody chose to measure and a corpus measures the shapes nobody chose, because a test file is written to pin an answer rather than to be fast, so a feature that is quick on the benchmark and quadratic on the long tail shows up here and nowhere else."
            )?;
            writeln!(f)?;
            writeln!(
                f,
                "A record is in the denominator when both engines answered it and both put a number on it. A record that failed on either side is never timed, because timing an error path measures the error path, and one under the floor on both sides is dropped because the two numbers being divided are then mostly the cost of starting a shell. Both engines are driven as sessions on a database file, which is what makes the number the cost of the record rather than the cost of everything above it in the file."
            )?;
            writeln!(f)?;
            writeln!(
                f,
                "The processor time reads 0.00 on nearly every record here and that is the meter running out of digits rather than a result. GNU time reports user and system time in hundredths of a second and rudb answers a corpus record in less than one of them, so the numerator is zero wherever the pin spent long enough to give the division a denominator. The column earns its place at benchmark sizes, where it is the one that catches an engine buying its wall clock with cores. At this size the two numbers to read are the clock and the peak."
            )?;
            writeln!(f)?;
            writeln!(
                f,
                "Read the wall clock here as the cost of answering a small question from cold, because that is what it is. A corpus record is a handful of rows and the query itself is under a millisecond on both engines, so most of what the clock sees is the shell starting, opening the file, reading the catalog and printing. The tight quartiles say the same thing: a spread that narrow over hundreds of records of very different shapes is a fixed cost rather than a query cost. The number for a query that does real work is the benchmark section above, and the two are on this page together for that reason."
            )?;
            writeln!(f)?;
            writeln!(f, "    records     {:>7}  measured on both engines", spent.measured)?;
            writeln!(
                f,
                "    one sided   {:>7}  one engine put a number on it and the other did not",
                spent.one_sided
            )?;
            writeln!(
                f,
                "    unmeasured  {:>7}  ran and neither engine could be measured",
                spent.unmeasured
            )?;
            writeln!(f)?;
            match spent.overall {
                None => {
                    writeln!(
                        f,
                        "No record was measured on both engines in that run, so there is no ratio over the whole corpus. The counts above say why."
                    )?;
                    writeln!(f)?;
                }
                Some(ratios) => {
                    writeln!(f, "### The whole corpus")?;
                    writeln!(f)?;
                    for (what, spread) in
                        [("time", ratios.time), ("cpu", ratios.cpu), ("memory", ratios.memory)]
                    {
                        writeln!(
                            f,
                            "    {what:<8}{:>8.2}   quartiles {:.2} to {:.2} over {} records",
                            spread.median, spread.low, spread.high, spread.count
                        )?;
                    }
                    writeln!(f)?;
                    if ratios.at_goal() {
                        writeln!(f, "All three medians are at or below the goal of a tenth.")?;
                    } else {
                        writeln!(
                            f,
                            "The goal is {:.1} on all three and this is not at it yet.",
                            Ratios::GOAL
                        )?;
                    }
                    writeln!(f)?;
                }
            }
            if !spent.files.is_empty() {
                writeln!(f, "### Per file")?;
                writeln!(f)?;
                writeln!(
                    f,
                    "Worst median wall clock first. A file with one measured record in it is left out, because one record is an anecdote and putting it in a table beside a file of two hundred invites somebody to read it as a trend."
                )?;
                writeln!(f)?;
                writeln!(
                    f,
                    "    {:<40}{:>9}{:>9}{:>9}{:>7}",
                    "file", "time", "cpu", "memory", "n"
                )?;
                for (file, ratios) in &spent.files {
                    writeln!(
                        f,
                        "    {:<40}{:>9.2}{:>9.2}{:>9.2}{:>7}",
                        fitted(file, 39),
                        ratios.time.median,
                        ratios.cpu.median,
                        ratios.memory.median,
                        ratios.time.count
                    )?;
                }
                writeln!(f)?;
            }
            if !spent.worst.is_empty() {
                writeln!(f, "### The worst {}", spent.worst.len())?;
                writeln!(f)?;
                writeln!(
                    f,
                    "This is the column that gets read. An engine that is even on the median and two hundred times slower on one record has a bug rather than a distribution, and a median hides that by construction. Each row is the file and the line the record starts on, which is enough to open it."
                )?;
                writeln!(f)?;
                writeln!(f, "    {:<44}{:>9}{:>9}{:>9}", "record", "time", "cpu", "memory")?;
                for one in &spent.worst {
                    writeln!(
                        f,
                        "    {:<44}{:>9.2}{:>9.2}{:>9.2}",
                        fitted(&one.name, 43),
                        one.time,
                        one.cpu,
                        one.memory
                    )?;
                }
                writeln!(f)?;
            }
            writeln!(f, "    measured    {} on {}", spent.stamp, spent.host)?;
            writeln!(f, "    engine      {} at {}", spent.rudb, spent.rudb_commit)?;
            writeln!(f, "    rudb-compat {}", spent.compat_commit)?;
            writeln!(f, "    duckdb      {}", spent.duckdb_version)?;
            writeln!(f)?;
            if spent.matches(p) {
                writeln!(
                    f,
                    "That is the same engine build on the same machine as the corpus numbers above."
                )?;
            } else {
                writeln!(
                    f,
                    "That is not the engine build and machine the corpus numbers above came from, and a ratio whose two sides came off different hardware is not a ratio."
                )?;
            }
            writeln!(f)?;
        }

        writeln!(f, "## What this page does not say yet")?;
        writeln!(f)?;
        writeln!(
            f,
            "Eleven numbers belong here, per section 11.2. These are the ones nothing computes today, each with the denominator it will be computed over and what has to exist before it can be. None of them is printed as a zero, because a zero is a measurement and these are not measured."
        )?;
        writeln!(f)?;
        for (what, needs) in MISSING {
            if what == FUNCTIONS && self.sweep.is_some() {
                continue;
            }
            if what == RESOURCES && self.cost.is_some() {
                continue;
            }
            if what == STATEMENTS && !self.run.kinds.is_empty() {
                continue;
            }
            writeln!(f, "    {what:<20}{needs}")?;
        }
        writeln!(f)?;

        writeln!(f, "## Provenance")?;
        writeln!(f)?;
        writeln!(f, "    when           {}", p.stamp)?;
        writeln!(f, "    machine        {}, {}", p.host, p.platform)?;
        writeln!(f, "    engine         {} at {}", p.rudb, p.rudb_commit)?;
        writeln!(f, "    rudb-compat    {}", p.compat_commit)?;
        writeln!(f, "    duckdb pin     {}", p.duckdb_pin)?;
        writeln!(f, "    duckdb binary  {}", p.duckdb_binary)?;
        writeln!(f, "    duckdb version {}", p.duckdb_version)?;
        writeln!(f, "    duckdb md5     {}", p.duckdb_hash)?;
        writeln!(f, "    duckdb pinned  {}", p.duckdb_pinned)?;
        if p.upstream {
            writeln!(f, "    corpus         {} at {}", p.corpus_ref, p.corpus_commit)?;
        } else {
            writeln!(f, "    corpus         not the upstream corpus")?;
        }
        writeln!(f, "    corpus path    {}", p.corpus_path)?;
        writeln!(f, "    seed           {}", p.seed)?;
        Ok(())
    }
}

/// The row of [`MISSING`] that a recorded sweep takes off the list.
const FUNCTIONS: &str = "function coverage";

/// The row of [`MISSING`] that a recorded cost run takes off the list.
const RESOURCES: &str = "resource ratios";

/// The row of [`MISSING`] that a run with records in it takes off the list.
///
/// Off on any run that got as far as sorting a record, which is every run over a corpus that is
/// there. It stays on for a run over an empty directory, where the honest thing to print is not a
/// coverage of zero.
const STATEMENTS: &str = "statement coverage";

/// The four numbers section 11.2 asks for that a page may have nothing behind.
///
/// Kept as data rather than as paragraphs so that deleting a row is the whole of the work when one
/// of them stops being one of these, and so that a reader can see how many there are. Three of the
/// four are measured somewhere now and are still on the list, because each of the three has a run
/// that has to have happened first, and a page written where it has not has nothing to carry. The
/// honest thing to print then is what it would take. Only the error levels are on the list because
/// nothing anywhere measures them, and that waits on milestone 6.
const MISSING: [(&str, &str); 4] = [
    (
        STATEMENTS,
        "over the 36 alternatives of the Statement rule, needs a run with records in it, which this was not",
    ),
    (
        FUNCTIONS,
        "over the 1159 names in duckdb_functions() on the pin, weighted and unweighted, needs a sweep beside these pages, which `rudb-compat coverage --out` writes",
    ),
    (
        "error levels",
        "five levels over the records where the pinned binary errored, needs the error comparison in section 8.2",
    ),
    (
        RESOURCES,
        "rudb over duckdb on time, processor time and peak resident set, as medians with the quartiles, over the whole corpus and per suite and over the worst twenty, needs a cost run beside these pages, which `rudb-compat cost --out` writes",
    ),
];

/// The header line of the series file.
#[must_use]
pub fn header() -> String {
    COLUMNS.join("\t")
}

/// The header line of the sweep file.
#[must_use]
pub fn sweep_header() -> String {
    SWEEP_COLUMNS.join("\t")
}

/// The header line of the cost file.
#[must_use]
pub fn cost_header() -> String {
    COST_COLUMNS.join("\t")
}

/// One cost run as the rows of that file, the whole corpus first.
///
/// Several rows and not one, because the page wants three granularities and a table with a column
/// per suite would have a column count that changed with the corpus. The scope column says which of
/// the three a row is, and [`Cost::latest`] reads them back into one value by the stamp and the
/// machine they share.
///
/// The quartile columns of a benchmark row repeat its median. A benchmark on its own is one number
/// on each axis and there is nothing else those columns could truthfully hold, and [`Worst`] does not
/// carry them so that nobody reads a spread into a repeat.
#[must_use]
pub fn cost_rows(costs: &Costs, p: &Provenance) -> Vec<String> {
    let mut rows = Vec::with_capacity(1 + costs.measured.len());
    let totals = [
        costs.measured.len().to_string(),
        costs.skipped.len().to_string(),
        costs.refused.len().to_string(),
    ];
    let mut push = |scope: &str, what: &str, ratios: &Ratios, share: f64| {
        let mut fields = vec![
            p.stamp.clone(),
            p.host.clone(),
            p.rudb.clone(),
            p.rudb_commit.clone(),
            p.compat_commit.clone(),
            p.duckdb_version.clone(),
            scope.to_owned(),
            what.to_owned(),
            ratios.time.count.to_string(),
        ];
        for spread in [&ratios.time, &ratios.cpu, &ratios.memory] {
            fields.push(format!("{:.4}", spread.median));
            fields.push(format!("{:.4}", spread.low));
            fields.push(format!("{:.4}", spread.high));
        }
        fields.push(format!("{share:.4}"));
        fields.extend(totals.iter().cloned());
        rows.push(fields.join("\t"));
    };
    if let Some(ratios) = costs.overall() {
        push(CORPUS, "everything measured", &ratios, share(&costs.measured, None));
    }
    for (group, ratios) in costs.per_group() {
        push(SUITE, &group, &ratios, share(&costs.measured, Some(&group)));
    }
    for one in costs.worst(WORST) {
        let flat = |value: f64| Spread { median: value, low: value, high: value, count: 1 };
        let ratios =
            Ratios { time: flat(one.time()), cpu: flat(one.cpu()), memory: flat(one.memory()) };
        push(BENCHMARK, &one.name, &ratios, one.load_share());
    }
    rows
}

/// The header line of the corpus cost file.
#[must_use]
pub fn record_header() -> String {
    RECORD_COLUMNS.join("\t")
}

/// One corpus cost run as the rows of that file, the whole corpus first.
///
/// The same arrangement [`cost_rows`] uses, and a record row repeats its median in the quartile
/// columns for the same reason a benchmark row does: one record is one number on each axis and
/// there is nothing else those columns could truthfully hold. [`WorstRecord`] does not carry them,
/// so that nobody reads a spread into a repeat.
#[must_use]
pub fn record_rows(spends: &Spends, p: &Provenance) -> Vec<String> {
    let mut rows = Vec::with_capacity(1 + spends.records.len());
    let totals = [
        spends.records.len().to_string(),
        (spends.ours_only + spends.theirs_only).to_string(),
        spends.unmeasured.to_string(),
    ];
    let mut push = |scope: &str, what: &str, ratios: &Ratios| {
        let mut fields = vec![
            p.stamp.clone(),
            p.host.clone(),
            p.rudb.clone(),
            p.rudb_commit.clone(),
            p.compat_commit.clone(),
            p.duckdb_version.clone(),
            scope.to_owned(),
            what.to_owned(),
            ratios.time.count.to_string(),
        ];
        for spread in [&ratios.time, &ratios.cpu, &ratios.memory] {
            fields.push(format!("{:.4}", spread.median));
            fields.push(format!("{:.4}", spread.low));
            fields.push(format!("{:.4}", spread.high));
        }
        fields.extend(totals.iter().cloned());
        rows.push(fields.join("\t"));
    };
    if let Some(ratios) = spends.overall() {
        push(CORPUS, "everything measured", &ratios);
    }
    for (file, ratios) in spends.per_file() {
        push(FILE, &file, &ratios);
    }
    for one in spends.worst(WORST) {
        let flat = |value: f64| Spread { median: value, low: value, high: value, count: 1 };
        let ratios =
            Ratios { time: flat(one.time()), cpu: flat(one.cpu()), memory: flat(one.memory()) };
        push(RECORD, &one.name(), &ratios);
    }
    rows
}

/// The median load share over some of what a run measured.
///
/// Printed beside every ratio because a page that said rudb was three times slower and did not say
/// that nine tenths of the number was `CREATE TABLE` would be a page that sends people to the wrong
/// file.
fn share(all: &[Measured], group: Option<&str>) -> f64 {
    let values: Vec<f64> = all
        .iter()
        .filter(|one| group.is_none_or(|group| one.group == group))
        .map(Measured::load_share)
        .collect();
    Spread::of(&values).map_or(0.0, |spread| spread.median)
}

/// A name cut to something a column can hold.
fn fitted(name: &str, width: usize) -> String {
    if name.chars().count() <= width {
        return name.to_owned();
    }
    name.chars().take(width.saturating_sub(3)).chain("...".chars()).collect()
}

/// One sweep as a row of that file.
///
/// The same fields in the same order as [`SWEEP_COLUMNS`], which a test checks, and which
/// `Sweep::parse` reads back by name rather than by position so that the two cannot drift apart
/// without the test noticing first.
#[must_use]
pub fn sweep_row(coverage: &Coverage, p: &Provenance) -> String {
    let mut fields = vec![
        p.stamp.clone(),
        p.host.clone(),
        p.rudb.clone(),
        p.rudb_commit.clone(),
        p.compat_commit.clone(),
        p.duckdb_version.clone(),
    ];
    for tally in [&coverage.names, &coverage.overloads] {
        fields.push(tally.total.to_string());
        fields.push(tally.passed.to_string());
        fields.push(tally.failed.to_string());
        fields.push(tally.untested.to_string());
    }
    fields.push(coverage.crashes.to_string());
    for why in Untested::ALL {
        let count = coverage.reasons.iter().find(|(one, _)| *one == why).map_or(0, |(_, n)| *n);
        fields.push(count.to_string());
    }
    fields.join("\t")
}

/// One run as a row of the series file.
///
/// The same fields in the same order as [`COLUMNS`], which a test checks, because a row that has
/// drifted from its header is worse than no row at all.
#[must_use]
pub fn row(run: &Isolated, p: &Provenance) -> String {
    let skips = run.skips;
    let fields = [
        p.stamp.clone(),
        p.host.clone(),
        p.rudb.clone(),
        p.rudb_commit.clone(),
        p.compat_commit.clone(),
        p.corpus_commit.clone(),
        p.duckdb_version.clone(),
        run.files.to_string(),
        run.attempted().to_string(),
        run.passed.to_string(),
        run.failed.to_string(),
        format!("{:.3}", run.rate()),
        (skips.conditional + skips.mode + skips.maybe).to_string(),
        skips.engine.to_string(),
        (skips.unsupported + skips.unreadable).to_string(),
        skips.machine.to_string(),
        run.reasons().count(Reason::WrongAnswer).to_string(),
        run.kinds.supported().len().to_string(),
        run.kinds.failing().len().to_string(),
        run.kinds.untouched().len().to_string(),
        run.kinds.unclassified.to_string(),
    ];
    fields.join("\t")
}

/// Write the page and append the row, and say where the page went.
///
/// The page is a new file every run and the series is appended to, which is section 11.4 made
/// mechanical: a page that is overwritten cannot go down in front of anybody, and a number that is
/// allowed to go down has to be one somebody can watch going down.
///
/// # Errors
///
/// When the directory cannot be made or either file cannot be written.
pub fn write(
    dir: &Path,
    run: &Isolated,
    p: &Provenance,
    sweep: Option<&Sweep>,
    cost: Option<&Cost>,
    spent: Option<&Spent>,
) -> Result<PathBuf, HarnessError> {
    std::fs::create_dir_all(dir)
        .map_err(|e| HarnessError::new(format!("cannot make {}: {e}", dir.display())))?;
    let page = dir.join(p.filename());
    let rendered = Page::of(run, p).with(sweep).with_cost(cost).with_records(spent).to_string();
    std::fs::write(&page, rendered)
        .map_err(|e| HarnessError::new(format!("cannot write {}: {e}", page.display())))?;
    append(&dir.join(SERIES), &header(), &row(run, p))?;
    Ok(page)
}

/// Write one function sweep down beside the pages, and say which file it went in.
///
/// No page of its own. A sweep is a handful of counts and a great many failing calls, the calls go
/// to whoever ran it, and the counts belong on the page the corpus run writes rather than on a
/// second page nobody would read beside the first.
///
/// # Errors
///
/// When the directory cannot be made or the file cannot be appended to.
pub fn record(dir: &Path, coverage: &Coverage, p: &Provenance) -> Result<PathBuf, HarnessError> {
    std::fs::create_dir_all(dir)
        .map_err(|e| HarnessError::new(format!("cannot make {}: {e}", dir.display())))?;
    let file = dir.join(SWEEPS);
    append(&file, &sweep_header(), &sweep_row(coverage, p))?;
    Ok(file)
}

/// Write one cost run down beside the pages, and say which file it went in.
///
/// No page of its own, the same as a sweep. The rows of the run go in together, so a file that was
/// read while this was writing has either none of a run in it or all of it rather than the corpus row
/// without the suites under it.
///
/// # Errors
///
/// When the directory cannot be made or the file cannot be appended to.
pub fn measured(dir: &Path, costs: &Costs, p: &Provenance) -> Result<PathBuf, HarnessError> {
    std::fs::create_dir_all(dir)
        .map_err(|e| HarnessError::new(format!("cannot make {}: {e}", dir.display())))?;
    let file = dir.join(COSTS);
    let rows = cost_rows(costs, p);
    if rows.is_empty() {
        return Err(HarnessError::new(
            "nothing was measured on both engines, so there is no cost row to write".to_owned(),
        ));
    }
    append(&file, &cost_header(), &rows.join("\n"))?;
    Ok(file)
}

/// Write one corpus cost run down beside the pages, and say which file it went in.
///
/// No page of its own, the same as a sweep and a cost run. The rows of the run go in together, so a
/// file that was read while this was writing has either none of a run in it or all of it rather
/// than the corpus row without the files under it.
///
/// # Errors
///
/// When the directory cannot be made or the file cannot be appended to.
pub fn spent(dir: &Path, spends: &Spends, p: &Provenance) -> Result<PathBuf, HarnessError> {
    std::fs::create_dir_all(dir)
        .map_err(|e| HarnessError::new(format!("cannot make {}: {e}", dir.display())))?;
    let file = dir.join(RECORDS);
    let rows = record_rows(spends, p);
    if rows.is_empty() {
        return Err(HarnessError::new(
            "no record was measured on both engines, so there is no row to write".to_owned(),
        ));
    }
    append(&file, &record_header(), &rows.join("\n"))?;
    Ok(file)
}

/// Add one row to a file, starting it with its header when it is not there yet.
pub(crate) fn append(path: &Path, header: &str, row: &str) -> Result<(), HarnessError> {
    use std::io::Write as _;
    let fresh = !path.exists();
    let mut file = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| HarnessError::new(format!("cannot open {}: {e}", path.display())))?;
    let text = if fresh { format!("{header}\n{row}\n") } else { format!("{row}\n") };
    file.write_all(text.as_bytes())
        .map_err(|e| HarnessError::new(format!("cannot write {}: {e}", path.display())))
}

/// The commit a lock file pins the engine at.
///
/// Read out of `Cargo.lock` rather than asked of the engine, because the engine does not know which
/// commit it was built from and the lock file is the thing that decided. A tree whose lock has
/// moved since the binary was built reports the lock, which is wrong for about the length of one
/// build and is the closest thing to the truth that is available here.
#[must_use]
pub fn locked(root: &Path) -> Option<String> {
    let text = std::fs::read_to_string(root.join("Cargo.lock")).ok()?;
    pinned(&text).map(|commit| short(&commit).to_owned())
}

/// The commit out of the text of a lock file.
fn pinned(lock: &str) -> Option<String> {
    let mut in_rudb = false;
    for line in lock.lines() {
        let line = line.trim();
        if line == "[[package]]" {
            in_rudb = false;
        }
        if line == "name = \"rudb\"" {
            in_rudb = true;
        }
        if in_rudb && line.starts_with("source = ") {
            return line.rsplit_once('#').map(|(_, commit)| commit.trim_matches('"').to_owned());
        }
    }
    None
}

/// The commit this harness is at, and whether the tree it ran from was clean.
///
/// A dirty tree is said out loud rather than hidden, because a page from a dirty tree cannot be
/// reproduced from the commit it names and a reader has no other way of knowing that.
fn checkout(root: &Path) -> String {
    let Some(commit) = git(root, &["rev-parse", "HEAD"]) else {
        return "unknown, this is not a checkout".to_owned();
    };
    match git(root, &["status", "--porcelain"]) {
        Some(changes) if !changes.is_empty() => format!("{}, dirty", short(&commit)),
        Some(_) => format!("{}, clean", short(&commit)),
        None => short(&commit).to_owned(),
    }
}

/// Run git in a directory and give back what it said, or nothing when it failed.
fn git(root: &Path, args: &[&str]) -> Option<String> {
    let out = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(args)
        .output()
        .ok()
        .filter(|out| out.status.success())?;
    Some(String::from_utf8_lossy(&out.stdout).trim().to_owned())
}

/// The first ten characters of a commit, which is what the page prints.
fn short(commit: &str) -> &str {
    let at = commit.char_indices().nth(10).map_or(commit.len(), |(at, _)| at);
    &commit[..at]
}

/// The md5 of a file, for the binary the run measured against.
///
/// Two builds of the same DuckDB commit with different flags call themselves the same version and
/// are not the same binary, and a resource ratio against one of them is not a resource ratio
/// against the other.
fn md5_of(path: &Path) -> String {
    match std::fs::read(path) {
        Ok(bytes) => crate::hash::md5_hex(&bytes),
        Err(e) => format!("cannot read the binary: {e}"),
    }
}

/// What the machine calls itself.
fn host() -> String {
    Command::new("hostname")
        .output()
        .ok()
        .filter(|out| out.status.success())
        .map(|out| String::from_utf8_lossy(&out.stdout).trim().to_owned())
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| "unknown".to_owned())
}

/// The operating system, the processor and the cores the run could see.
fn platform() -> String {
    let cores = std::thread::available_parallelism().map_or(0, std::num::NonZero::get);
    format!("{} {}, {cores} cores", std::env::consts::OS, std::env::consts::ARCH)
}

/// An instant written out, in UTC, to the second.
///
/// UTC and not local time because these rows are compared across four machines that are not all in
/// one place, and a series whose rows are each in their own time zone is not ordered.
#[must_use]
pub fn stamp(unix: u64) -> String {
    let (year, month, day, hour, minute, second) = parts(unix);
    format!("{year:04}-{month:02}-{day:02} {hour:02}:{minute:02}:{second:02} UTC")
}

/// The year, month, day, hour, minute and second of an instant, in UTC.
///
/// The date part is Howard Hinnant's civil from days, which is the algorithm underneath every date
/// library there is. It is written out here rather than depended on, because this crate has one
/// dependency and it is the engine, and a date on a report is not worth a second one.
fn parts(unix: u64) -> (i64, u32, u32, u64, u64, u64) {
    let days = i64::try_from(unix / 86_400).unwrap_or(0);
    let rest = unix % 86_400;
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if month <= 2 { year + 1 } else { year };
    let month = u32::try_from(month).unwrap_or(1);
    let day = u32::try_from(day).unwrap_or(1);
    (year, month, day, rest / 3600, (rest % 3600) / 60, rest % 60)
}

